import sys

def count_snake(n: int) -> int:
    if n < 10:
        return 0

    s = str(n)
    m = len(s)
    ans = 0

    for length in range(2, m):
        for first in range(1, 10):
            ans += first ** (length - 1)

    first_digit = int(s[0])

    for first in range(1, first_digit):
        ans += first ** (m - 1)

    top = first_digit
    for i in range(1, m):
        limit = int(s[i])
        remaining = m - i - 1

        choices_less_than_limit = min(top, limit)
        ans += choices_less_than_limit * (top ** remaining)

        if limit >= top:
            return ans

    ans += 1
    return ans


def main():
    L, R = map(int, sys.stdin.readline().split())
    print(count_snake(R) - count_snake(L - 1))


if __name__ == "__main__":
    main()
